import Foundation
import Security

/// Developer/App Store builds share a data-protection Keychain item through the
/// existing App Group entitlement. Local ad-hoc builds use the macOS login
/// Keychain with an explicit ACL for the containing app and its Finder extension.
/// Local keys are freshly generated by the host each launch: the host never
/// accepts an existing login-Keychain value chosen by another process.
/// Neither mode falls back to a constant, UserDefaults or a shared plaintext file.
nonisolated final class IPCKeyStore: @unchecked Sendable {
    static let shared = IPCKeyStore()
    private let lock = NSLock()
    private var cached: Data?

    struct KeychainError: Error {
        let status: OSStatus
    }

    func key() throws -> Data {
        try lock.withLock {
#if RC_LOCAL_BUILD
            if Bundle.main.bundleIdentifier == "cn.wflixu.RClick.FinderSyncExt" {
                // Re-read on each message so restarting the host rotates the
                // local session without leaving Finder pinned to the old key.
                return try Self.validated(Self.read(Self.query))
            }
            if let cached { return cached }
            let data = try Self.randomKey()
            var attributes = Self.query
            attributes[kSecValueData as String] = data
            attributes[kSecAttrAccess as String] = try Self.localAccess()
            let removed = SecItemDelete(Self.query as CFDictionary)
            guard removed == errSecSuccess || removed == errSecItemNotFound else {
                throw KeychainError(status: removed)
            }
            let added = SecItemAdd(attributes as CFDictionary, nil)
            guard added == errSecSuccess else { throw KeychainError(status: added) }
#else
            if let cached { return cached }
            let query = Self.query
            let data: Data
            do {
                data = try Self.validated(Self.read(query))
            } catch let error as KeychainError where error.status == errSecItemNotFound {
                let random = try Self.randomKey()
                var attributes = query
                attributes[kSecValueData as String] = random
                attributes[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
                let added = SecItemAdd(attributes as CFDictionary, nil)
                if added == errSecDuplicateItem {
                    // Both processes can start together. Always use the winner's
                    // key; never cache a key that was not successfully stored.
                    data = try Self.validated(Self.read(query))
                } else {
                    guard added == errSecSuccess else { throw KeychainError(status: added) }
                    data = random
                }
            }
#endif
            cached = data
            return data
        }
    }

    private static func validated(_ data: Data) throws -> Data {
        guard data.count == 32 else { throw KeychainError(status: errSecDecode) }
        return data
    }

    private static func randomKey() throws -> Data {
        var data = Data(count: 32)
        let status = data.withUnsafeMutableBytes { bytes in
            SecRandomCopyBytes(kSecRandomDefault, bytes.count, bytes.baseAddress!)
        }
        guard status == errSecSuccess else { throw KeychainError(status: status) }
        return data
    }

    private static var query: [String: Any] {
        var query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: "hmac-sha256-v2",
        ]
#if RC_LOCAL_BUILD
        query[kSecAttrService as String] = "cn.wflixu.RClick.ipc.local"
#else
        query[kSecAttrService as String] = "cn.wflixu.RClick.ipc"
        query[kSecUseDataProtectionKeychain as String] = true
        query[kSecAttrAccessGroup as String] = SharedAppGroup.identifier
        query[kSecAttrSynchronizable as String] = false
#endif
        return query
    }

    private static func read(_ query: [String: Any]) throws -> Data {
        var query = query
        query[kSecReturnData as String] = true
        query[kSecMatchLimit as String] = kSecMatchLimitOne
        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        guard status == errSecSuccess else { throw KeychainError(status: status) }
        guard let data = result as? Data else { throw KeychainError(status: errSecDecode) }
        return data
    }

#if RC_LOCAL_BUILD
    private static func localAccess() throws -> SecAccess {
        let bundle = Bundle.main
        let hostURL = bundle.bundleIdentifier == "cn.wflixu.RClick.FinderSyncExt"
            ? bundle.bundleURL.deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            : bundle.bundleURL
        guard let host = Bundle(url: hostURL), host.bundleIdentifier == "cn.wflixu.RClick",
              let finder = Bundle(url: hostURL.appendingPathComponent("Contents/PlugIns/FinderSyncExt.appex")),
              finder.bundleIdentifier == "cn.wflixu.RClick.FinderSyncExt" else {
            throw KeychainError(status: errSecAuthFailed)
        }
        let trusted: [SecTrustedApplication] = try [host, finder].map { app in
            guard let executable = app.executableURL else { throw KeychainError(status: errSecAuthFailed) }
            var application: SecTrustedApplication?
            let status = executable.path.withCString { SecTrustedApplicationCreateFromPath($0, &application) }
            guard status == errSecSuccess, let application else { throw KeychainError(status: status) }
            return application
        }
        var access: SecAccess?
        let status = SecAccessCreate("RClick IPC" as CFString, trusted as CFArray, &access)
        guard status == errSecSuccess, let access else { throw KeychainError(status: status) }
        return access
    }
#endif
}
